WITH cleaned AS (SELECT *, CASE WHEN country IN ('US', 'JP') THEN 'Core' ELSE 'Other' END AS country_group FROM sessions WHERE browser <> 'Edge' AND started_at > DATE '2023-09-03'), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM cleaned), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS new_group_flag_tier, SUM(CASE WHEN browser = 'Edge' THEN new_group_flag ELSE 0 END) AS edge_new_group_flag, ROUND(SUM(island_id) / NULLIF(COUNT(CASE WHEN country = 'DE' THEN 1 END), 0), 2) AS island_id_per_de, COUNT(*) AS event_count, GROUPING(DATE_TRUNC('WEEK', started_at)) AS gid FROM sessionized GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', started_at), CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('WEEK', started_at)), ()) ORDER BY week_start DESC
